import{_ as e,o as d,c as n,a2 as a}from"./chunks/framework.CxN14L7e.js";const h=JSON.parse('{"title":"Documents","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/documents.md","filePath":"concepts/documents.md"}'),s={name:"concepts/documents.md"};function o(i,t,c,r,l,p){return d(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h1><p>Documents are the core resource in eFinSign. Each document represents a PDF that can be signed by one or more signers.</p><h2 id="document-lifecycle" tabindex="-1">Document Lifecycle <a class="header-anchor" href="#document-lifecycle" aria-label="Permalink to &quot;Document Lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>draft  →  pending  →  completed</span></span>
<span class="line"><span>                    →  expired (voided)</span></span>
<span class="line"><span>                    →  declined</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td><code>draft</code></td><td>Document created, signers being added. Not yet sent.</td></tr><tr><td><code>pending</code></td><td>Sent for signing. Awaiting signer action.</td></tr><tr><td><code>completed</code></td><td>All signers have signed. Final PDF generated.</td></tr><tr><td><code>expired</code></td><td>Voided by the sender before completion.</td></tr><tr><td><code>declined</code></td><td>A signer declined to sign.</td></tr></tbody></table><h2 id="creating-a-document" tabindex="-1">Creating a Document <a class="header-anchor" href="#creating-a-document" aria-label="Permalink to &quot;Creating a Document&quot;">​</a></h2><p>Upload a PDF via multipart form data:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /documents</span></span>
<span class="line"><span>Content-Type: multipart/form-data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>file: contract.pdf</span></span>
<span class="line"><span>title: Service Agreement 2026</span></span></code></pre></div><p>The document starts in <code>draft</code> status. Add signers and fields before sending.</p><h2 id="adding-signers-and-fields" tabindex="-1">Adding Signers and Fields <a class="header-anchor" href="#adding-signers-and-fields" aria-label="Permalink to &quot;Adding Signers and Fields&quot;">​</a></h2><p>After creating a document, add signers with their signature fields:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /documents/:id/signers</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;Jane Smith&quot;,</span></span>
<span class="line"><span>  &quot;email&quot;: &quot;jane@example.com&quot;,</span></span>
<span class="line"><span>  &quot;order&quot;: 1,</span></span>
<span class="line"><span>  &quot;fields&quot;: [</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;signature&quot;, &quot;page&quot;: 1, &quot;x&quot;: 100, &quot;y&quot;: 500, &quot;w&quot;: 200, &quot;h&quot;: 50 },</span></span>
<span class="line"><span>    { &quot;type&quot;: &quot;date&quot;,     &quot;page&quot;: 1, &quot;x&quot;: 350, &quot;y&quot;: 500, &quot;w&quot;: 150, &quot;h&quot;: 30 }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="field-types" tabindex="-1">Field Types <a class="header-anchor" href="#field-types" aria-label="Permalink to &quot;Field Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>signature</code></td><td>Hand-drawn or uploaded signature</td></tr><tr><td><code>initials</code></td><td>Signer&#39;s initials</td></tr><tr><td><code>name</code></td><td>Signer&#39;s typed full name</td></tr><tr><td><code>date</code></td><td>Auto-filled date</td></tr><tr><td><code>text</code></td><td>Free text input</td></tr><tr><td><code>checkbox</code></td><td>Checkbox</td></tr><tr><td><code>checkmark</code></td><td>Checkmark</td></tr><tr><td><code>full_name</code></td><td>Pre-filled full name</td></tr><tr><td><code>title</code></td><td>Signer&#39;s title</td></tr></tbody></table><h3 id="signing-order" tabindex="-1">Signing Order <a class="header-anchor" href="#signing-order" aria-label="Permalink to &quot;Signing Order&quot;">​</a></h3><p>Set <code>order</code> to control sequential signing:</p><ul><li><code>0</code> or unset: Any order (parallel signing)</li><li><code>1, 2, 3...</code>: Signer 1 must sign before signer 2 can access the document</li></ul><h2 id="sending-for-signing" tabindex="-1">Sending for Signing <a class="header-anchor" href="#sending-for-signing" aria-label="Permalink to &quot;Sending for Signing&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /documents/:id/send</span></span></code></pre></div><p>Requires at least one signer. Changes status from <code>draft</code> to <code>pending</code>. In production, emails are sent to all signers.</p><h2 id="downloading" tabindex="-1">Downloading <a class="header-anchor" href="#downloading" aria-label="Permalink to &quot;Downloading&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /documents/:id/download?type=signed</span></span>
<span class="line"><span>GET /documents/:id/download?type=original</span></span></code></pre></div><p>Returns the PDF as binary. Use <code>type=signed</code> for the completed signed copy.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/documents</code></td><td>Create and upload</td></tr><tr><td><code>GET</code></td><td><code>/documents</code></td><td>List (paginated, filterable)</td></tr><tr><td><code>GET</code></td><td><code>/documents/:id</code></td><td>Get with signers and fields</td></tr><tr><td><code>PATCH</code></td><td><code>/documents/:id</code></td><td>Update metadata</td></tr><tr><td><code>DELETE</code></td><td><code>/documents/:id</code></td><td>Delete (draft only)</td></tr><tr><td><code>GET</code></td><td><code>/documents/:id/download</code></td><td>Download PDF</td></tr><tr><td><code>GET</code></td><td><code>/documents/:id/audit-log</code></td><td>Audit trail</td></tr><tr><td><code>POST</code></td><td><code>/documents/:id/send</code></td><td>Send for signing</td></tr><tr><td><code>POST</code></td><td><code>/documents/:id/void</code></td><td>Void</td></tr><tr><td><code>POST</code></td><td><code>/documents/:id/remind</code></td><td>Remind signers</td></tr></tbody></table>`,25)])])}const g=e(s,[["render",o]]);export{h as __pageData,g as default};
